// The CLI verb parity check (the lead's acceptance for slice 7b): at D8 the `cerberus` on PATH
// becomes this build, so every command path and flag of main's CLI must exist here, or carry a
// decision below with an owner or an obsolete record, and a reason. testdata/clitree/main.tree is
// main's full cobra tree, generated by testdata/clitree/tree_gen_on_main.go.txt on a checkout of
// main. A new old verb, a verb dropped here, or a decision for something that is now present
// fails the test. docs/conversion-notes.md ("CLI verb parity") summarizes the table.

// Owners a decision may name. A slice owns a verb that returns with it; "$LEGACY until F" is the
// old binary, kept as $LEGACY through the cutover; obsolete and replaced need their evidence in
// the reason.
const (
	ownerSlice9  = "slice 9"  // MCP
	ownerSlice10 = "slice 10" // migrate-from, export-legacy
	ownerSlice11 = "slice 11" // console
	ownerLegacy  = "slice 12; $LEGACY until F"
	obsolete     = "obsolete"
	replaced     = "replaced"
)

type parityDecision struct{ owner, reason string }

// cliDecisions are keyed by an old command path (it and everything under it) or by
// "<path> --<flag>" (that flag alone).
var cliDecisions = map[string]parityDecision{
	// Root.
	"cerberus --config": {replaced, "the config is the manifest defaults plus the SUBSTRATE_CONFIG override file (conversion-notes, Paths); the root takes no value flag (TestRootHasNoValueFlags)"},
	"cerberus --db":     {replaced, "the database path is database.sqlite.path in the override file (conversion-notes, Environment)"},

	// Approvals: decision 0.1 makes deciding the owner's console session alone.
	"cerberus approvals revoke":            {obsolete, "decision 0.1: revoking is the owner's console act (POST /api/approvals/{id}/revoke, person-only)"},
	"cerberus approvals ack-break-glass":   {obsolete, "decision 0.1: the owner acknowledges a break-glass follow-up on the console (POST /api/approvals/{id}/ack-break-glass, person-only)"},
	"cerberus approvals enroll":            {obsolete, "decision 0.1: passkey approvals are dropped; no enrollment"},
	"cerberus approvals keys":              {obsolete, "decision 0.1: passkey approvals are dropped; the passkey registry is kept in place, unused"},
	"cerberus approvals enrollment-policy": {obsolete, "decision 0.1: passkey approvals are dropped"},
	"cerberus approvals --listen":          {obsolete, "decision 0.1: the address of the old `cerberus web` console the approval and passkey links pointed at; the console is the serving Cerberus, and approve/deny name its /approvals page"},

	// Audit: verify is here; the rest read the chain in <data>/audit.
	"cerberus config migrate": {ownerSlice10, "migrated the old config.yaml in place; the import of the old tree is migrate-from"},

	// Connectors.
	"cerberus connectors exec --break-glass":                   {obsolete, "break glass needs a person at the CLI (principal human via cli, gate.breakGlassOnCall); under decision 0.1 a key is an agent via api, local trust an agent via mcp_stdio and the console a person via web, so no caller can break glass; an approval now comes from the owner on the console, then --approval <id>. The admin routes serve no break-glass form"},
	"cerberus connectors exec --reason":                        {obsolete, "the reason of --break-glass, obsolete with it"},
	"cerberus connectors plugin exec":                          {obsolete, "one-shot run of an unreviewed plugin directory: main itself answers 410 PluginDirRetired on the socket and the console (cerbapi socket_server.go, webui server.go); no client in inventory-clients.md calls it; managed install --dev plus connectors exec replace it"},
	"cerberus connectors plugin health":                        {obsolete, "one-shot health of a plugin directory, as plugin exec: 410 PluginDirRetired on main; managed health <id> replaces it"},
	"cerberus connectors plugin managed install --yes":         {obsolete, "the permissive-posture shortcut that skipped the typed id: accepting a review is the owner's (lead's ruling (a), decision 0.1), with no path that skips the owner"},
	"cerberus connectors plugin managed load --accept-changes": {replaced, "accepting a changed bundle is `connectors plugin managed review <id>` (conversion-notes, Admin lane)"},

	// The process and its units.
	"cerberus daemon":    {ownerLegacy, "replaced by `cerberus serve` under the new unit (slice 12's descriptor); the old daemon verbs stay on $LEGACY until F"},
	"cerberus install":   {ownerLegacy, "wrote the old daemon unit; the new unit comes from the fleet-install descriptor (slice 12)"},
	"cerberus uninstall": {ownerLegacy, "as install"},
	"cerberus path":      {replaced, "printed the old go-apppaths layout and ~/.cerberus/config.yaml; the new paths are `cerberus config` (the resolved config: database path, adopted root) and conversion-notes, Paths"},
	"cerberus init":      {ownerLegacy, "created the old ~/.cerberus tree and config.yaml; the new data directory is created by serve, the import by migrate-from"},
	"cerberus web":       {ownerSlice11, "the console moves into the serving process (slice 11); the old console unit is retired"},
	"cerberus mcp-http":  {ownerSlice9, "MCP over HTTP moves to /mcp on the same host; tokens become API keys"},

	// Resource verbs not carried yet, and the break-glass flags.
	"cerberus resource apply --break-glass":        {obsolete, "break glass needs a person at the CLI, which no caller is under decision 0.1 (see connectors exec --break-glass); legacy-routes.md carries no break-glass form for L7/L8; approvals come from the owner on the console, then --approval <id>"},
	"cerberus resource apply --reason":             {obsolete, "the reason of --break-glass"},
	"cerberus resource deploy --break-glass":       {obsolete, "as resource apply --break-glass"},
	"cerberus resource deploy --reason":            {obsolete, "the reason of --break-glass"},
	"cerberus resource reload --break-glass":       {obsolete, "as resource apply --break-glass"},
	"cerberus resource reload --reason":            {obsolete, "the reason of --break-glass"},
	"cerberus resource remove --break-glass":       {obsolete, "as resource apply --break-glass"},
	"cerberus resource remove --reason":            {obsolete, "the reason of --break-glass"},
	"cerberus resource stop --break-glass":         {obsolete, "as resource apply --break-glass"},
	"cerberus resource stop --reason":              {obsolete, "the reason of --break-glass"},
	"cerberus resource sync --break-glass":         {obsolete, "as resource apply --break-glass"},
	"cerberus resource sync --reason":              {obsolete, "the reason of --break-glass"},
	"cerberus resource ensure-fresh --break-glass": {obsolete, "as resource apply --break-glass; ensure-fresh passed it to the verb it chose"},
	"cerberus resource ensure-fresh --reason":      {obsolete, "the reason of --break-glass"},
}

// oldCommand is one line of main.tree.
type oldCommand struct {
	path  string
	flags []string // "--name" or "--name/-x"
}

func readOldTree(t *testing.T) []oldCommand {
	t.Helper()
	f, err := os.Open(filepath.Join("testdata", "clitree", "main.tree"))
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = f.Close() }()
	var out []oldCommand
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		path, flags, _ := strings.Cut(sc.Text(), "\t")
		out = append(out, oldCommand{path: path, flags: strings.Fields(flags)})
	}
	if err = sc.Err(); err != nil {
		t.Fatal(err)
	}
	if len(out) < 100 {
		t.Fatalf("main.tree has %d commands; regenerate it", len(out))
	}
	return out
}

// newTree is this build's command tree by path, built as main builds it with the modules a read
// verb starts.
func newTree(t *testing.T) map[string]*cobra.Command {
	t.Helper()
	ctx := context.Background()
	started, err := boot.StartWith(ctx, substrateApp, pickModules(readOnlyModules), substrateConfigJSON, boot.Options{})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = started.Stop(ctx) })
	root := rootCommand(ctx, &cerberus{app: started.App, home: os.Getenv("HOME")})
	tree := map[string]*cobra.Command{}
	var walk func(c *cobra.Command)
	walk = func(c *cobra.Command) {
		tree[c.CommandPath()] = c
		for _, sub := range c.Commands() {
			walk(sub)
		}
	}
	walk(root)
	return tree
}

// decided is the decision covering key: the key itself, or for a command path an ancestor's.
func decided(key string) (string, bool) {
	if _, ok := cliDecisions[key]; ok {
		return key, true
	}
	if strings.Contains(key, " --") {
		return "", false
	}
	for p := key; strings.Contains(p, " "); {
		p = p[:strings.LastIndex(p, " ")]
		if _, ok := cliDecisions[p]; ok {
			return p, true
		}
	}
	return "", false
}

func TestEveryOldVerbIsHereOrDecided(t *testing.T) {
	tree := newTree(t)
	used := map[string]bool{}
	var missing []string
	for _, old := range readOldTree(t) {
		c, ok := tree[old.path]
		if !ok {
			if key, d := decided(old.path); d {
				used[key] = true
			} else {
				missing = append(missing, old.path)
			}
			continue
		}
		for _, f := range old.flags {
			name, short, _ := strings.Cut(strings.TrimPrefix(f, "--"), "/-")
			// A group's own persistent flag is in Flags only once cobra has merged it.
			got := c.Flags().Lookup(name)
			if got == nil {
				got = c.PersistentFlags().Lookup(name)
			}
			if got == nil {
				got = c.InheritedFlags().Lookup(name)
			}
			if got != nil && got.Shorthand == short {
				continue
			}
			key := old.path + " --" + name
			if _, d := cliDecisions[key]; d {
				used[key] = true
				continue
			}
			if got == nil {
				missing = append(missing, key)
			} else {
				missing = append(missing, key+" (shorthand -"+got.Shorthand+", old -"+short+")")
			}
		}
	}
	sort.Strings(missing)
	if len(missing) > 0 {
		t.Errorf("old CLI paths and flags missing here with no decision (port them, or add a decision with an owner or an obsolete record and its reason):\n  %s", strings.Join(missing, "\n  "))
	}
	var stale []string
	for key, d := range cliDecisions {
		if !used[key] {
			stale = append(stale, key)
		}
		if d.owner == "" || d.reason == "" {
			t.Errorf("decision %q needs an owner and a reason", key)
		}
	}
	sort.Strings(stale)
	if len(stale) > 0 {
		t.Errorf("decisions for paths or flags that are now here or were never on main; remove them:\n  %s", strings.Join(stale, "\n  "))
	}
}

// The check sees a flag by its pflag lookup, so a renamed or dropped flag fails it.
func TestParityCheckSeesFlags(t *testing.T) {
	tree := newTree(t)
	apply := tree["cerberus resource apply"]
	if apply == nil || apply.Flags().Lookup("ack") == nil || apply.Flags().Lookup("break-glass") != nil {
		t.Fatalf("resource apply: %v", apply)
	}
	if list := tree["cerberus resource list"]; list == nil || list.Flags().ShorthandLookup("o") == nil {
		t.Fatal("resource list -o")
	}
}

// newVerbs are verbs this build adds that main never had: they are not in main.tree, so the parity
// check cannot see them; this keeps them from disappearing (slices 10a and 10b).
var newVerbs = map[string][]string{
	"cerberus migrate-from":   {"old-home", "old-db", "manifest", "old-anchor-account", "output"},
	"cerberus manifest write": {"old-home", "old-db", "out", "anchor-account"},
	"cerberus manifest check": {"manifest", "old-home", "old-db", "anchor-account"},
	"cerberus export-legacy":  {"since", "old-home", "old-db", "old-anchor-account", "only", "check-legacy-files", "d3-copy", "output"},
	"cerberus import-standby": {"from", "output"},
}

func TestNewVerbsArePresent(t *testing.T) {
	tree := newTree(t)
	for path, flags := range newVerbs {
		c := tree[path]
		if c == nil {
			t.Errorf("%s is missing", path)
			continue
		}
		for _, f := range flags {
			if c.Flags().Lookup(f) == nil {
				t.Errorf("%s --%s is missing", path, f)
			}
		}
	}
	for _, old := range readOldTree(t) {
		if _, isNew := newVerbs[old.path]; isNew {
			t.Errorf("%s is in main.tree: move it out of newVerbs", old.path)
		}
	}
}
